'use strict';
const $=id=>document.getElementById(id), sample='ప్రియమైన మిత్రమా,\n\nమన తెలుగు భాష ఎంతో మధురమైనది.\nప్రతి అక్షరంలో ఒక అందం ఉంది.\nమన జ్ఞాపకాలను పదిలంగా ఉంచుదాం.\n\nపాత లేఖలు, కథలు, అనుభవాలు\nరాబోయే తరాలకు అందిద్దాం.\nఅక్షరాలకు కొత్త జీవితం ఇద్దాం.\n\nఇట్లు,\nమీ మిత్రుడు';
let raw=sample,blocks=[],currentFile=null,isSample=true,zoom=100,rotation=0,queue=[],activeIndex=-1,library=[],api='',model=null;
try{library=JSON.parse(localStorage.getItem('akshara-library')||'[]');if(!Array.isArray(library))library=[];api=localStorage.getItem('akshara-api')||'';if(localStorage.getItem('akshara-theme')==='dark')document.body.classList.add('dark')}catch{}
const tell=message=>{$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4000)};
const graphemes=s=>Array.from(new Intl.Segmenter('te',{granularity:'grapheme'}).segment(s),x=>x.segment);
function bundle(){return {schema_version:'1.0',filename:currentFile?.name||$('filename').textContent,illustrative_sample:isSample,raw_markdown:raw,transcription:$('transcript').value,transcription_nfc:$('transcript').value.normalize('NFC'),reviewed:$('reviewed').checked,blocks,model,exported_at:new Date().toISOString()}}
function update(){const t=$('transcript').value;$('textStats').textContent=`${graphemes(t).length} graphemes · ${t.trim()?t.trim().split(/\s+/u).length:0} words`;$('rawOutput').textContent=raw;$('jsonOutput').textContent=JSON.stringify(bundle(),null,2);$('reviewStatus').textContent=$('reviewed').checked?'HUMAN VERIFIED':'NEEDS REVIEW';$('docCount').textContent=library.length;}
function setText(text,original=true){$('transcript').value=text;if(original)raw=text;$('reviewed').checked=false;update()}
function page(name){document.querySelectorAll('.page').forEach(x=>x.hidden=x.id!==name);document.querySelectorAll('nav [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===name));$('breadcrumb').textContent=({studio:'Transcription studio',library:'Document library',evaluation:'Evaluation lab',datasets:'Dataset registry',developers:'Developer tools'})[name];if(name==='library')renderLibrary();history.replaceState(null,'','#'+name)}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('selected',x===b));$('transcript').hidden=b.dataset.tab!=='review';$('rawOutput').hidden=b.dataset.tab!=='raw';$('jsonOutput').hidden=b.dataset.tab!=='json';update()});
$('transcript').oninput=()=>{$('reviewed').checked=false;update()};$('reviewed').onchange=update;
$('themeBtn').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('akshara-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}};
$('guideBtn').onclick=()=>$('guide').showModal();
function settings(){$('apiUrl').value=api;$('settings').showModal()}
$('settingsBtn').onclick=settings;$('devConnect').onclick=settings;
async function health(url){const response=await fetch(url+'/api/health',{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error(`HTTP ${response.status}`);return response.json()}
$('testConnection').onclick=async()=>{try{const u=new URL($('apiUrl').value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('Use an HTTP(S) URL without credentials.');const target=u.href.replace(/\/$/,'');$('healthMessage').textContent='Checking server…';const h=await health(target);api=target;try{localStorage.setItem('akshara-api',api)}catch{}$('healthMessage').textContent=h.model_ready?'Model ready. Uploaded images will be sent to this server.':'Server connected; model unavailable. Set INDIC_OCR_REPO and install official model dependencies.';$('connectionStatus').textContent=h.model_ready?'● Model connected':'○ Server connected · model unavailable';tell('Connection saved.')}catch(e){$('healthMessage').textContent='Connection failed: '+e.message}};
function transform(){$('documentImage').style.transform=`rotate(${rotation}deg)`;$('documentImage').style.width=zoom+'%';$('documentImage').style.maxWidth=zoom>100?'none':'100%';$('samplePaper').style.transform=`rotate(${rotation-1.5}deg) scale(${zoom/100})`;$('zoomLabel').textContent=zoom+'%'}
$('zoomIn').onclick=()=>{zoom=Math.min(200,zoom+10);transform()};$('zoomOut').onclick=()=>{zoom=Math.max(40,zoom-10);transform()};$('rotateBtn').onclick=()=>{rotation=(rotation+90)%360;transform();tell('Preview rotated. Original upload is unchanged.')};
$('uploadBtn').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>addFiles(e.target.files);
let imageUrl=null;
function stash(){if(activeIndex>=0)queue[activeIndex].state=bundle()}
function selectFile(index){stash();activeIndex=index;currentFile=queue[index].file;isSample=false;blocks=[];model=null;zoom=100;rotation=0;if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=URL.createObjectURL(currentFile);$('documentImage').src=imageUrl;$('documentImage').hidden=false;$('samplePaper').hidden=true;$('filename').textContent=currentFile.name;$('filemeta').textContent=`${(currentFile.size/1024/1024).toFixed(2)} MB · original preserved`;$('pageLabel').textContent=`${index+1} / ${queue.length}`;$('reviewNotice').textContent='Ready for transcription. Connect your model or enter a verified transcript manually.';$('sourceHint').textContent='View controls do not modify the source file';const state=queue[index].state;if(state){raw=state.raw_markdown;blocks=state.blocks||[];model=state.model;setText(state.transcription,false);$('reviewed').checked=state.reviewed;update()}else setText('');transform();renderQueue();page('studio')}
function renderQueue(){let q=$('queue');if(!q){q=document.createElement('div');q.id='queue';q.className='queue';document.querySelector('.editor-grid').before(q)}q.replaceChildren();queue.forEach((item,i)=>{const b=document.createElement('button');b.className='button'+(i===activeIndex?' active':'');b.textContent=item.file.name;b.title=item.file.name;b.onclick=()=>selectFile(i);q.append(b)})}
function addFiles(files){const valid=Array.from(files).filter(f=>['image/jpeg','image/png','image/webp'].includes(f.type)&&f.size<=20*1024*1024);if(!valid.length){tell('Choose JPG, PNG or WebP images up to 20 MB each.');return}if(valid.length!==files.length)tell('Some files were skipped: unsupported format or over 20 MB.');const start=queue.length;queue.push(...valid.map(file=>({file,state:null})));selectFile(start)}
['dragover','dragleave','drop'].forEach(event=>$('dropzone').addEventListener(event,e=>{e.preventDefault();$('dropzone').classList.toggle('dragging',event==='dragover');if(event==='drop')addFiles(e.dataTransfer.files)}));
$('sampleBtn').onclick=()=>{stash();activeIndex=-1;currentFile=null;isSample=true;blocks=[];model=null;zoom=100;rotation=0;$('documentImage').hidden=true;$('samplePaper').hidden=false;$('filename').textContent='A letter worth preserving';$('filemeta').textContent='Illustrative sample · not an OCR prediction';$('pageLabel').textContent='SAMPLE';$('reviewNotice').textContent='Sample text for exploring the editor. Connect a model to transcribe your own documents.';setText(sample);transform();renderQueue()};
$('runBtn').onclick=async()=>{if(!currentFile)return tell('Upload an image first. The sample is illustrative.');if(!api){settings();return}const capturedIndex=activeIndex;const file=currentFile;$('runBtn').disabled=true;try{const form=new FormData();form.append('file',file);const response=await fetch(api+'/api/predict',{method:'POST',body:form,signal:AbortSignal.timeout(600000)});const result=await response.json();if(!response.ok)throw Error(result.detail||'OCR failed');if(typeof result.markdown!=='string')throw Error('Server response must include a markdown string.');const state={raw_markdown:result.markdown,transcription:result.markdown,reviewed:false,blocks:result.blocks||[],model:result.model||null};queue[capturedIndex].state=state;if(activeIndex===capturedIndex){raw=state.raw_markdown;blocks=state.blocks;model=state.model;setText(state.transcription,false);$('reviewNotice').textContent='Model output requires human verification. Detection scores are not text confidence.'}tell('Transcription received. Review before export.')}catch(e){tell('Transcription failed: '+e.message)}finally{$('runBtn').disabled=false}};
$('importBtn').onclick=()=>$('jsonInput').click();$('jsonInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error('JSON exceeds 5 MB.');const j=JSON.parse(await f.text());const text=j.markdown??j.raw_markdown;if(typeof text!=='string')throw Error('Expected markdown or raw_markdown string.');if(j.blocks&&!Array.isArray(j.blocks))throw Error('blocks must be an array.');blocks=j.blocks||[];model=j.model||null;isSample=!!j.illustrative_sample;setText(text);$('filename').textContent=f.name;$('filemeta').textContent='Imported OCR output · review required';$('reviewNotice').textContent='Imported transcription. Pair it with the correct original image before verification.';tell('OCR output imported.')}catch(err){tell('Import failed: '+err.message)}e.target.value=''};
$('normalizeBtn').onclick=()=>{setText($('transcript').value.normalize('NFC'),false);tell('Editable text normalized. Raw output preserved.')};
$('copyBtn').onclick=async()=>{try{await navigator.clipboard.writeText($('transcript').value);tell('Text copied.')}catch{tell('Clipboard unavailable. Select and copy the text manually.')}};
function download(text,name,type){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('exportBtn').onclick=()=>{const fmt=$('exportFormat').value;const name=($('filename').textContent.replace(/\.[^.]+$/,'').replace(/[^\p{L}\p{N}_-]+/gu,'_')||'transcription');download(fmt==='json'?JSON.stringify(bundle(),null,2):$('transcript').value,name+'.'+fmt,fmt==='json'?'application/json':'text/plain;charset=utf-8');tell('Document exported'+($('reviewed').checked?'.':' · marked as unverified in JSON.'))};
function persist(){try{localStorage.setItem('akshara-library',JSON.stringify(library));update();return true}catch{tell('Storage is full or unavailable. Export a JSON bundle instead.');return false}}
$('saveBtn').onclick=()=>{if(!$('transcript').value.trim())return tell('Add a transcription first.');const record={...bundle(),id:crypto.randomUUID(),saved_at:new Date().toISOString()};library.unshift(record);if(!persist()){library.shift();return}tell('Saved to your local library.');};
function renderLibrary(){const target=$('libraryList');target.replaceChildren();const term=$('searchLibrary').value.toLowerCase();const items=library.filter(x=>(x.filename+' '+x.transcription).toLowerCase().includes(term));if(!items.length){const p=document.createElement('div');p.className='callout';p.textContent=library.length?'No matching documents.':'Your library starts here. Save a transcription from the studio.';target.append(p)}items.forEach(item=>{const card=document.createElement('article');card.className='library-card';const text=document.createElement('div'),title=document.createElement('h3'),meta=document.createElement('p');title.textContent=item.filename;meta.textContent=`${item.reviewed?'Human verified':'Needs review'} · ${item.illustrative_sample?'Illustrative sample · ':''}${new Date(item.saved_at).toLocaleDateString()}`;text.append(title,meta);const actions=document.createElement('div');actions.className='card-actions';for(const [label,fn]of [['Open',()=>{stash();activeIndex=-1;currentFile=null;isSample=item.illustrative_sample;blocks=item.blocks||[];model=item.model;raw=item.raw_markdown;setText(item.transcription,false);$('reviewed').checked=item.reviewed;$('filename').textContent=item.filename;$('filemeta').textContent='Library text · original image not stored';$('samplePaper').hidden=true;$('documentImage').hidden=true;$('reviewNotice').textContent='Original image is not stored in the library. Upload the correct source to review.';update();page('studio')}],['JSON',()=>download(JSON.stringify(item,null,2),'review.json','application/json')],['Delete',()=>{if(!confirm('Delete this saved transcription from this device?'))return;library=library.filter(x=>x.id!==item.id);persist();renderLibrary()}]]){const b=document.createElement('button');b.className='button';b.textContent=label;b.onclick=fn;actions.append(b)}card.append(text,actions);target.append(card)})}
$('searchLibrary').oninput=renderLibrary;$('clearLibrary').onclick=()=>{if(confirm('Delete all saved transcriptions from this device?')){library=[];persist();renderLibrary()}};
function distance(a,b){let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=0;i<a.length;i++){const next=[i+1];for(let j=0;j<b.length;j++)next.push(Math.min(next[j]+1,row[j+1]+1,row[j]+(a[i]===b[j]?0:1)));row=next}return row[b.length]}
$('evaluateBtn').onclick=()=>{const gold=$('gold').value,pred=$('prediction').value;if(!gold.trim())return tell('A verified reference is required.');if(graphemes(gold).length>10000||graphemes(pred).length>10000)return tell('Use the Python CLI for transcripts over 10,000 graphemes.');const g=gold.normalize('NFC'),p=pred.normalize('NFC'),gs=graphemes(g);const words=g.trim().split(/\s+/u);const values=[['Grapheme CER',(100*distance(gs,graphemes(p))/gs.length).toFixed(2)+'%'],['Word error rate',(100*distance(words,p.trim()?p.trim().split(/\s+/u):[])/words.length).toFixed(2)+'%'],['Raw exact match',gold===pred?'Yes':'No']];$('metricResults').replaceChildren();values.forEach(([label,value])=>{const a=document.createElement('article');a.className='metric';const s=document.createElement('small'),b=document.createElement('strong');s.textContent=label;b.textContent=value;a.append(s,b);$('metricResults').append(a)})};
const sources=[['PLHWTR-1.0 · ICDAR 2024','Page images + training transcripts. Usage terms need clarification; no archive downloaded.','https://ilocr.iiit.ac.in/icdar_2024_hwd/dataset.html'],['IIIT-INDIC-HW-WORDS · Telugu','Word images · CC BY 4.0 stated on portal. Download access unresolved; observed pairs: 0.','https://ilocr.iiit.ac.in/dataset/23/'],['IHTR 2023 · Telugu','Separate word-level version. License/version reconciliation required before use.','https://ilocr.iiit.ac.in/ihtr/dataset.html'],['IHDR 2025 · Telugu','Camera-captured pages. Academic/research use only; archive access must be verified.','https://ilocr.iiit.ac.in/icdar_2025_Indic_HDR/dataset.html']];sources.forEach(([name,desc,url])=>{const a=document.createElement('article');a.className='dataset-card';const d=document.createElement('div'),h=document.createElement('h3'),p=document.createElement('p'),link=document.createElement('a');h.textContent=name;p.textContent=desc;link.href=url;link.target='_blank';link.rel='noopener';link.className='button';link.textContent='Official source ↗';d.append(h,p);a.append(d,link);$('datasetList').append(a)});
setText(sample);page(['studio','library','evaluation','datasets','developers'].includes(location.hash.slice(1))?location.hash.slice(1):'studio');
